import{_ as d,a as e,b as a,c as r,d as i,e as l}from"./chunks/arm_10pin_jtag_connector_pinout.5fpEPKOC.js";import{_ as o,o as h,c as s,al as n}from"./chunks/framework.7vp1BMOE.js";const g=JSON.parse('{"title":"mRo Pixhawk Flight Controller (Pixhawk 1)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_controller/mro_pixhawk.md","filePath":"uk/flight_controller/mro_pixhawk.md"}'),b={name:"uk/flight_controller/mro_pixhawk.md"};function c(p,t,u,k,m,f){return h(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="mro-pixhawk-flight-controller-pixhawk-1" tabindex="-1">mRo Pixhawk Flight Controller (Pixhawk 1) <a class="header-anchor" href="#mro-pixhawk-flight-controller-pixhawk-1" aria-label="Permalink to &quot;mRo Pixhawk Flight Controller (Pixhawk 1)&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 не розробляє цей (або будь-який інший) автопілот. Contact the <a href="https://store.mrobotics.io/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The <em>mRo Pixhawk<sup>®</sup></em> is a hardware compatible version of the original <a href="./../flight_controller/pixhawk">Pixhawk 1</a>. It runs PX4 on the <a href="https://nuttx.apache.org/" target="_blank" rel="noreferrer">NuttX</a> OS.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The controller can be used as a drop-in replacement for the 3DR<sup>®</sup> <a href="./../flight_controller/pixhawk">Pixhawk 1</a>. The main difference is that it is based on the <a href="https://pixhawk.org/" target="_blank" rel="noreferrer">Pixhawk-project</a> <strong>FMUv3</strong> open hardware design, which corrects a bug that limited the original Pixhawk 1 to 1MB of flash.</p></div><p><img src="'+d+'" alt="mRo Pixhawk Image"></p><p>Assembly/setup instructions for use with PX4 are provided here: <a href="./../assembly/quick_start_pixhawk">Pixhawk Wiring Quickstart</a></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This autopilot is <a href="./../flight_controller/autopilot_pixhawk_standard">supported</a> by the PX4 maintenance and test teams.</p></div><h2 id="основні-характеристики" tabindex="-1">Основні характеристики <a class="header-anchor" href="#основні-характеристики" aria-label="Permalink to &quot;Основні характеристики&quot;">​</a></h2><ul><li><p>Мікропроцесор:</p><ul><li>32-bit STM32F427 Cortex<sup>®</sup> M4 core з FPU</li><li>168 MHz/256 KB RAM/2 MB Flash</li><li>32 bit STM32F103 відмовостійкий копроцесор</li><li>24 MHz/8 KB RAM/64 KB Flash</li></ul></li><li><p>Датчики:</p><ul><li>ST Micro L3GD20 3-axis 16-бітний гіроскоп</li><li>ST Micro LSM303D 3-вісний 14-бітний акселерометр / магнітометр</li><li>Invensense<sup>®</sup> MPU 6000 3-вісний акселерометр/гіроскоп</li><li>MEAS MS5611 барометр</li></ul></li><li><p>Інтерфейси:</p><ul><li>5x UART (послідовні порти), один високої потужності, 2x з контролем потоку ГВП</li><li>2x CAN</li><li>Вхід, сумісний з приймачами Spektrum DSM / DSM2 / DSM-X® Satellite до DX8 (DX9 та вище не підтримуються)</li><li>Futaba<sup>®</sup> S.BUS сумісний вхід та вихід</li><li>Сигнал суми PPM</li><li>Вхід RSSI (ШІМ або напруга)</li><li>I2C</li><li>SPI</li><li>3.3 та 6.6V ADC входи</li><li>Зовнішній порт microUSB</li></ul></li><li><p>Система живлення:</p><ul><li>Ідеальний діодний контролер з автоматичним перемиканням на резервне живлення</li><li>Сервопривід високої потужності (7 В) і готовий до великого струму</li><li>Усі периферійні виводи захищені від перевантаження по струму, усі входи захищені від електростатичного розряду</li></ul></li><li><p>Вага та розміри:</p><ul><li>Вага: 38г (1,31 унції)</li><li>Ширина: 50 мм (1.96&quot;)</li><li>Товщина: 15.5 мм (.613&quot;)</li><li>Довжина: 81.5 мм (3.21&quot;)</li></ul></li></ul><h2 id="доступність" tabindex="-1">Доступність <a class="header-anchor" href="#доступність" aria-label="Permalink to &quot;Доступність&quot;">​</a></h2><ul><li><a href="https://store.mrobotics.io/Genuine-PixHawk-1-Barebones-p/mro-pixhawk1-bb-mr.htm" target="_blank" rel="noreferrer">Bare Bones</a> - Just the board (useful as a 3DR Pixhawk replacement)</li><li><a href="https://store.mrobotics.io/Genuine-PixHawk-Flight-Controller-p/mro-pixhawk1-minkit-mr.htm" target="_blank" rel="noreferrer">mRo Pixhawk 2.4.6 Essential Kit!</a> - Everything except for telemetry radios</li><li><a href="https://store.mrobotics.io/product-p/mro-pixhawk1-fullkit-mr.htm" target="_blank" rel="noreferrer">mRo Pixhawk 2.4.6 Cool Kit! (Limited edition)</a> - Everything you need including telemetry radios</li></ul><h2 id="збірка-прошивки" tabindex="-1">Збірка прошивки <a class="header-anchor" href="#збірка-прошивки" aria-label="Permalink to &quot;Збірка прошивки&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Most users will not need to build this firmware! It is pre-built and automatically installed by <em>QGroundControl</em> when appropriate hardware is connected.</p></div><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_fmu-v3_default</span></span></code></pre></div><h2 id="відладочні-порти" tabindex="-1">Відладочні порти <a class="header-anchor" href="#відладочні-порти" aria-label="Permalink to &quot;Відладочні порти&quot;">​</a></h2><h3 id="порт-консолі" tabindex="-1">Порт Консолі <a class="header-anchor" href="#порт-консолі" aria-label="Permalink to &quot;Порт Консолі&quot;">​</a></h3><p>The <a href="./../debug/system_console">PX4 System Console</a> runs on the port labeled <a href="#serial-4-5-port">SERIAL4/5</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A convenient way to connect to the console is to use a <a href="https://github.com/Zubax/bugface_bf1" target="_blank" rel="noreferrer">Zubax BugFace BF1</a>, as it comes with connectors that can be used with several different Pixhawk devices. Simply connect the 6-pos DF13 1:1 cable on the <a href="https://github.com/Zubax/bugface_bf1" target="_blank" rel="noreferrer">Zubax BugFace BF1</a> to the Pixhawk <code>SERIAL4/5</code> port.</p><p><img src="'+e+'" alt="Zubax BugFace BF1"></p></div><p>The pinout is standard serial pinout, designed to connect to a <a href="https://www.digikey.com/en/products/detail/TTL-232R-3V3/768-1015-ND/1836393" target="_blank" rel="noreferrer">3.3V FTDI</a> cable (5V tolerant).</p><table tabindex="0"><thead><tr><th>3DR Pixhawk 1</th><th></th><th>FTDI</th><th></th></tr></thead><tbody><tr><td>1</td><td>+5V (red)</td><td></td><td>N/C</td></tr><tr><td>2</td><td>S4 Tx</td><td></td><td>N/C</td></tr><tr><td>3</td><td>S4 Rx</td><td></td><td>N/C</td></tr><tr><td>4</td><td>S5 Tx</td><td>5</td><td>FTDI RX (yellow)</td></tr><tr><td>5</td><td>S5 Rx</td><td>4</td><td>FTDI TX (orange)</td></tr><tr><td>6</td><td>GND</td><td>1</td><td>FTDI GND (black)</td></tr></tbody></table><p>The wiring for an FTDI cable to a 6-pos DF13 1:1 connector is shown in the figure below.</p><p><img src="'+a+'" alt="Console Connector"></p><p>The complete wiring is shown below.</p><p><img src="'+r+'" alt="Console Debug"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>For information on how to <em>use</em> the console see: <a href="./../debug/system_console">System Console</a>.</p></div><h3 id="swd-port" tabindex="-1">SWD Port <a class="header-anchor" href="#swd-port" aria-label="Permalink to &quot;SWD Port&quot;">​</a></h3><p>The <a href="./../debug/swd_debug">SWD</a> (JTAG) ports are hidden under the cover (which must be removed for hardware debugging). There are separate ports for FMU and IO, as highlighted below.</p><p><img src="'+i+'" alt="Pixhawk SWD"></p><p>The ports are ARM 10-pin JTAG connectors, which you will probably have to solder. The pinout for the ports is shown below (the square markers in the corners above indicates pin 1).</p><p><img src="'+l+'" alt="ARM 10-Pin connector pinout"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>All Pixhawk FMUv2 boards have a similar SWD port.</p></div><h2 id="схема-розташування-виводів" tabindex="-1">Схема розташування виводів <a class="header-anchor" href="#схема-розташування-виводів" aria-label="Permalink to &quot;Схема розташування виводів&quot;">​</a></h2><h4 id="telem1-telem2-порти" tabindex="-1">TELEM1, TELEM2 порти <a class="header-anchor" href="#telem1-telem2-порти" aria-label="Permalink to &quot;TELEM1, TELEM2 порти&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Pin</th><th>Сигнал</th><th>Вольтаж</th></tr></thead><tbody><tr><td>1 (red)</td><td>VCC</td><td>+5V</td></tr><tr><td>2 (blk)</td><td>TX (OUT)</td><td>+3.3V</td></tr><tr><td>3 (blk)</td><td>RX (IN)</td><td>+3.3V</td></tr><tr><td>4 (blk)</td><td>CTS (IN)</td><td>+3.3V</td></tr><tr><td>5 (blk)</td><td>RTS (OUT)</td><td>+3.3V</td></tr><tr><td>6 (blk)</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="порт-gps" tabindex="-1">Порт GPS <a class="header-anchor" href="#порт-gps" aria-label="Permalink to &quot;Порт GPS&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Pin</th><th>Сигнал</th><th>Вольтаж</th></tr></thead><tbody><tr><td>1 (red)</td><td>VCC</td><td>+5V</td></tr><tr><td>2 (blk)</td><td>TX (OUT)</td><td>+3.3V</td></tr><tr><td>3 (blk)</td><td>RX (IN)</td><td>+3.3V</td></tr><tr><td>4 (blk)</td><td>CAN2 TX</td><td>+3.3V</td></tr><tr><td>5 (blk)</td><td>CAN2 RX</td><td>+3.3V</td></tr><tr><td>6 (blk)</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="serial-4-5-port" tabindex="-1">SERIAL 4/5 port <a class="header-anchor" href="#serial-4-5-port" aria-label="Permalink to &quot;SERIAL 4/5 port&quot;">​</a></h4><p>Due to space constraints two ports are on one connector.</p><table tabindex="0"><thead><tr><th>Pin</th><th>Сигнал</th><th>Вольтаж</th></tr></thead><tbody><tr><td>1 (red)</td><td>VCC</td><td>+5V</td></tr><tr><td>2 (blk)</td><td>TX (#4)</td><td>+3.3V</td></tr><tr><td>3 (blk)</td><td>RX (#4)</td><td>+3.3V</td></tr><tr><td>4 (blk)</td><td>TX (#5)</td><td>+3.3V</td></tr><tr><td>5 (blk)</td><td>RX (#5)</td><td>+3.3V</td></tr><tr><td>6 (blk)</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="adc-6-6v" tabindex="-1">ADC 6.6V <a class="header-anchor" href="#adc-6-6v" aria-label="Permalink to &quot;ADC 6.6V&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Pin</th><th>Сигнал</th><th>Вольтаж</th></tr></thead><tbody><tr><td>1 (red)</td><td>VCC</td><td>+5V</td></tr><tr><td>2 (blk)</td><td>ADC IN</td><td>up to +6.6V</td></tr><tr><td>3 (blk)</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="adc-3-3v" tabindex="-1">ADC 3.3V <a class="header-anchor" href="#adc-3-3v" aria-label="Permalink to &quot;ADC 3.3V&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Pin</th><th>Сигнал</th><th>Вольтаж</th></tr></thead><tbody><tr><td>1 (red)</td><td>VCC</td><td>+5V</td></tr><tr><td>2 (blk)</td><td>ADC IN</td><td>до +3.3V</td></tr><tr><td>3 (blk)</td><td>GND</td><td>GND</td></tr><tr><td>4 (blk)</td><td>ADC IN</td><td>до +3.3V</td></tr><tr><td>5 (blk)</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="i2c" tabindex="-1">I2C <a class="header-anchor" href="#i2c" aria-label="Permalink to &quot;I2C&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Pin</th><th>Сигнал</th><th>Вольтаж</th></tr></thead><tbody><tr><td>1 (red)</td><td>VCC</td><td>+5V</td></tr><tr><td>2 (blk)</td><td>SCL</td><td>+3.3 (pullups)</td></tr><tr><td>3 (blk)</td><td>SDA</td><td>+3.3 (pullups)</td></tr><tr><td>4 (blk)</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="can" tabindex="-1">CAN <a class="header-anchor" href="#can" aria-label="Permalink to &quot;CAN&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Pin</th><th>Сигнал</th><th>Вольтаж</th></tr></thead><tbody><tr><td>1 (red)</td><td>VCC</td><td>+5V</td></tr><tr><td>2 (blk)</td><td>CAN_H</td><td>+12V</td></tr><tr><td>3 (blk)</td><td>CAN_L</td><td>+12V</td></tr><tr><td>4 (blk)</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="spi" tabindex="-1">SPI <a class="header-anchor" href="#spi" aria-label="Permalink to &quot;SPI&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Pin</th><th>Сигнал</th><th>Вольтаж</th></tr></thead><tbody><tr><td>1 (red)</td><td>VCC</td><td>+5V</td></tr><tr><td>2 (blk)</td><td>SPI_EXT_SCK</td><td>+3.3</td></tr><tr><td>3 (blk)</td><td>SPI_EXT_MISO</td><td>+3.3</td></tr><tr><td>4 (blk)</td><td>SPI_EXT_MOSI</td><td>+3.3</td></tr><tr><td>5 (blk)</td><td>!SPI_EXT_NSS</td><td>+3.3</td></tr><tr><td>6 (blk)</td><td>!GPIO_EXT</td><td>+3.3</td></tr><tr><td>7 (blk)</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="power" tabindex="-1">POWER <a class="header-anchor" href="#power" aria-label="Permalink to &quot;POWER&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Pin</th><th>Сигнал</th><th>Вольтаж</th></tr></thead><tbody><tr><td>1 (red)</td><td>VCC</td><td>+5V</td></tr><tr><td>2 (blk)</td><td>VCC</td><td>+5V</td></tr><tr><td>3 (blk)</td><td>CURRENT</td><td>+3.3V</td></tr><tr><td>4 (blk)</td><td>VOLTAGE</td><td>+3.3V</td></tr><tr><td>5 (blk)</td><td>GND</td><td>GND</td></tr><tr><td>6 (blk)</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="switch" tabindex="-1">SWITCH <a class="header-anchor" href="#switch" aria-label="Permalink to &quot;SWITCH&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Pin</th><th>Сигнал</th><th>Вольтаж</th></tr></thead><tbody><tr><td>1 (red)</td><td>VCC</td><td>+3.3V</td></tr><tr><td>2 (blk)</td><td>!IO_LED_SAFETY</td><td>GND</td></tr><tr><td>3 (blk)</td><td>SAFETY</td><td>GND</td></tr></tbody></table><h2 id="налаштування-послідовного-порту" tabindex="-1">Налаштування послідовного порту <a class="header-anchor" href="#налаштування-послідовного-порту" aria-label="Permalink to &quot;Налаштування послідовного порту&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>Пристрій</th><th>Порт</th></tr></thead><tbody><tr><td>UART1</td><td>/dev/ttyS0</td><td>IO debug</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>TELEM1 (керування потоком)</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>TELEM2 (керування потоком)</td></tr><tr><td>UART4</td><td></td><td></td></tr><tr><td>UART7</td><td>CONSOLE</td><td></td></tr><tr><td>UART8</td><td>SERIAL4</td><td></td></tr></tbody></table><h2 id="налаштування-послідовного-порту-1" tabindex="-1">Налаштування послідовного порту <a class="header-anchor" href="#налаштування-послідовного-порту-1" aria-label="Permalink to &quot;Налаштування послідовного порту&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>Пристрій</th><th>Порт</th></tr></thead><tbody><tr><td>UART1</td><td>/dev/ttyS0</td><td>IO debug</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>TELEM1 (керування потоком)</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>TELEM2 (керування потоком)</td></tr><tr><td>UART4</td><td></td><td></td></tr><tr><td>UART7</td><td>CONSOLE</td><td></td></tr><tr><td>UART8</td><td>SERIAL4</td><td></td></tr></tbody></table><h2 id="креслення" tabindex="-1">Креслення <a class="header-anchor" href="#креслення" aria-label="Permalink to &quot;Креслення&quot;">​</a></h2><p>The board is based on the <a href="https://pixhawk.org/" target="_blank" rel="noreferrer">Pixhawk-project</a> <strong>FMUv3</strong> open hardware design.</p><ul><li><a href="https://github.com/pixhawk/Hardware/raw/master/FMUv3_REV_D/Schematic%20Print/Schematic%20Prints.PDF" target="_blank" rel="noreferrer">FMUv3 schematic</a> -- Schematic and layout</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>As a CC-BY-SA 3.0 licensed Open Hardware design, all schematics and design files are <a href="https://github.com/pixhawk/Hardware" target="_blank" rel="noreferrer">available</a>.</p></div>',62)])])}const w=o(b,[["render",c]]);export{g as __pageData,w as default};
